import {installUpdates} from './updates.js';
import {appVersion,buildId,socialLinks} from './app-meta.js';
import {examSchedule,examDates,examSession} from './schedule.js';
import {subjects,branches,colleges,colors,allTopics,quizQuestions,pyqs} from './data.js';
import {scoreQuiz,recordTime,validateBackup,yearCounts,buildPlan,dateKey,uid} from './core.js';
const KEY='exam-dost-v1';const blank=()=>({profile:null,topics:{},saved:[],marked:[],attempts:[],tasks:[],exams:{},settings:{theme:'light',goal:'Complete important topics',availability:[60,90,90,90,90,90,120],slot:'Evening',autoPlan:false}});
let state=blank();let storageOK=true;try{const raw=localStorage.getItem(KEY);if(raw)state={...state,...validateBackup(JSON.parse(raw))};}catch(e){storageOK=false;}
state.settings={...blank().settings,...state.settings};
let unitFilter='all',savedOnly=false,resultFilter='all',planFilter='today',navigatorOpen=false,installPrompt=null,currentStart=null,toastTimer;
const scrolls=new Map();const viewStates=new Map();let previousHash=location.hash;const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify({app:'exam-dost',version:1,state}));storageOK=true;}catch{storageOK=false;toast('Storage is unavailable or full. Export a backup before leaving.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 5C9 3 5 3 2 4v16c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v16"/>',document:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8"/>',trophy:'<path d="M7 3h10v6a5 5 0 0 1-10 0zM7 5H3v3a4 4 0 0 0 5 4m9-7h4v3a4 4 0 0 1-5 4m-4 2v5m-5 2h10"/>',network:'<circle cx="5" cy="12" r="3"/><circle cx="18" cy="5" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 11 7-5m-7 7 7 5"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',nodes:'<circle cx="12" cy="4" r="3"/><circle cx="4" cy="19" r="3"/><circle cx="20" cy="19" r="3"/><path d="m10 7-5 9m9-9 5 9M7 19h10"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',tree:'<rect x="9" y="2" width="6" height="6" rx="1"/><rect x="1" y="17" width="6" height="6" rx="1"/><rect x="17" y="17" width="6" height="6" rx="1"/><path d="M12 8v5H4v4m8-4h8v4"/>',bell:'<path d="M5 16h14l-2-3V8A5 5 0 0 0 7 8v5zm5 4h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/>',clock:'<circle cx="12" cy="13" r="9"/><path d="M12 8v5l3 2M9 1h6"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M3 22v-3a9 9 0 0 1 18 0v3"/>',save:'<path d="M6 3h12v19l-6-4-6 4z"/>',download:'<path d="M12 2v14m-5-5 5 5 5-5M3 17v5h18v-5"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M3 17v5h18v-5"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',grid:'<rect x="2" y="2" width="7" height="7" rx="1"/><rect x="15" y="2" width="7" height="7" rx="1"/><rect x="2" y="15" width="7" height="7" rx="1"/><rect x="15" y="15" width="7" height="7" rx="1"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>'};
function icon(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;}
function btn(text,action,cls='',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function link(text,path,cls=''){return `<a class="${cls}" href="#${path}">${text}</a>`;}
function go(path){location.hash=path;}
const route=()=>location.hash.slice(1).split('/').filter(Boolean);const subject=id=>subjects.find(s=>s.id===id)||subjects[0];
function hero(tag,title,sub,tone='green',art='study'){return `<section class="hero ${tone}"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${sub}</p></div><div class="hero-art">${art==='study'?'<img src="./assets/study.png" alt="Books and study calendar">':`<img src="./assets/${art==='quiz'?'quiz':art==='paper'?'paper':'study'}.png" alt="">`}</div></section>`;}
function profileInitial(){return esc(Array.from(state.profile?.name.trim()||'?')[0].toLocaleUpperCase());}
function profileButton(){return link(`<span aria-hidden="true">${profileInitial()}</span><span class="sr-only">My Profile</span>`,'/profile','round profile-link profile-initial');}
function top(title,sub=''){return `<header class="subheader"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${profileButton()}</header>`;}
function header(){return `<header class="main-header"><a class="wordmark" href="#/home"><img src="./assets/logo.svg" alt=""><span>Exam Dost</span></a><div class="header-actions">${btn(icon('bell'),'reminders','round','aria-label="Study reminders"')}${profileButton()}</div></header>`;}
function nav(active){return `<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['subjects','book','Subjects'],['pyqs','document','PYQs'],['quiz','trophy','Quiz']].map(([id,ic,t])=>link(`<img class="nav-icon-3d" src="./assets/nav-${id}.webp" alt="" width="32" height="32"><span>${t}</span>`,'/'+id,active===id?'active':'')).join('')}</nav>`;}
function back(path='/home'){return `<div class="back-dock">${link(icon('back')+' Back',path,'back-pill')}</div>`;}
function page(html,{active=null,parent='/home',main=false}={}){return `<div class="app-shell">${main?header():''}<main id="main">${html}</main>${active?nav(active):back(parent)}</div>`;}
function percent(ts){let done=ts.filter(t=>state.topics[t.id]).length;return {done,total:ts.length,pct:ts.length?Math.round(done/ts.length*100):0};}
function bar(p,color='green'){return `<div class="progress-track ${color}" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p}%"></span></div>`;}
function ring(p){return `<div class="ring" style="--p:${p}"><b>${p}%</b></div>`;}
function subjectCards(target,sub=''){return `<div class="subject-list">${subjects.map(s=>{let p=percent(s.units.flatMap(u=>u.topics));return link(`<span class="subject-icon ${s.color}">${icon(s.icon)}</span><div class="subject-content"><span class="badge ${s.color}">${s.short}</span><h3>${s.name}</h3><p>${sub||`${p.done} of ${p.total} topics completed`}</p>${sub?'':bar(p.pct,s.color)}</div>${icon('chevron')}`,target(s),'subject-card card');}).join('')}</div>`;}
function setup(edit=false){let p=state.profile||{};const legacyBranches={'CSE (Artificial Intelligence & Machine Learning)':branches[4],'CSE (Data Science)':branches[5],'CSE (Cyber Security)':branches[2],'CSE (Internet of Things)':branches[3]};const selectedBranch=legacyBranches[p.branch]||p.branch;return `<div class="app-shell setup-shell"><main>${!edit?'<div class="wordmark setup-brand"><img src="./assets/logo.svg" alt=""><span>Exam Dost</span></div>':top('Edit profile')}${hero('YOUR STUDY COMPANION',edit?'Make it yours.':'Your exam journey<br>starts here.','Tell us a little about yourself.','blue')}<form id="profile-form" class="card form-card"><h2>${edit?'Your details':'Set up your profile'}</h2><label>Your name<input name="name" required maxlength="100" placeholder="Enter your name" autocomplete="name" value="${esc(p.name||'')}"></label><label>College<input name="college" list="college-list" required maxlength="180" placeholder="Search or enter your college" value="${esc(p.college||'')}"><datalist id="college-list">${colleges.map(c=>`<option value="${esc(c)}">`).join('')}</datalist></label><label>Branch<select name="branch" required><option value="">Select your branch</option>${selectedBranch&&!branches.includes(selectedBranch)?`<option selected>${esc(selectedBranch)}</option>`:''}${branches.map(b=>`<option ${selectedBranch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><p class="muted small">CSE and supported specialisation branches share the same study content.</p><button class="primary full">${edit?'Save changes':'Get started'} ${icon('arrow')}</button></form><p class="footnote">No account needed. Set up once on this device.</p></main>${edit?back('/profile'):''}</div>`;}
function home(){let p=percent(allTopics),today=dateKey();let tasks=state.tasks.filter(t=>t.date===today).slice(0,3);let upcoming=subjects.filter(s=>examDates[s.id]&&examDates[s.id]>=today).sort((a,b)=>examDates[a.id].localeCompare(examDates[b.id]))[0];let days=upcoming?Math.ceil((new Date(examDates[upcoming.id]+'T00:00:00')-new Date(today+'T00:00:00'))/86400000):0;return page(`${hero('YOUR STUDY COMPANION','A little progress,<br>every day.',`Let’s make today count, ${esc(state.profile.name.split(' ')[0])}.`)}<section class="card next-exam"><div><span class="badge green">Next exam</span><h2>${upcoming?upcoming.name:'Exams complete. Well done.'}</h2><p>${upcoming?`${days===0?'Today':days+' days to go'} · ${formatDate(examDates[upcoming.id])} · ${examSession.label}`:'Your scheduled exams have finished. Keep learning at your own pace.'}</p>${link('View exam schedule '+icon('arrow'),'/planner','text-link')}</div><span class="calendar-art">${upcoming?`<strong>${days}</strong><small>DAYS</small>`:icon('calendar')}</span></section><section class="card summary mint"><div><h2>Your preparation</h2><p>${p.done} of ${p.total} topics completed</p>${bar(p.pct)}</div>${ring(p.pct)}</section><div class="section-heading"><h2>Today’s plan</h2>${link('View all '+icon('arrow'),'/planner','text-link')}</div>${tasks.length?`<section class="card task-list">${tasks.map(taskRow).join('')}</section>`:`<section class="card empty"><span class="subject-icon green">${icon('calendar')}</span><h3>A fresh start awaits.</h3><p>Choose your study time and build today’s plan.</p>${link('Plan my preparation','/planner','button primary')}</section>`}<div class="section-heading"><h2>Keep learning</h2></div><div class="shortcut-grid">${link(icon('document')+'<div><h3>Important PYQs</h3><p>Questions that matter</p></div>','/pyqs','shortcut mint')}${link(icon('trophy')+'<div><h3>Master Quiz</h3><p>Test your concepts</p></div>','/quiz/master','shortcut lavender')}</div><p class="footnote">Your progress stays on this device.</p>`,{active:'home',main:true});}
function subjectsPage(){let p=percent(allTopics);return page(`${hero('YOUR SYLLABUS','My Subjects','One topic at a time. You’ve got this.')}<section class="card summary"><div><p>Overall syllabus progress</p><h2>${p.done} of ${p.total} topics completed</h2><p>6 subjects · Your progress, in one place</p></div>${ring(p.pct)}</section><div class="section-heading"><h2>Your subjects</h2><span>6 subjects</span></div>${subjectCards(s=>'/subjects/'+s.id)}`,{active:'subjects',main:true});}
function subjectPage(id){let s=subject(id),p=percent(s.units.flatMap(u=>u.topics));return page(`${top(s.name,'Subjects / Unit overview')}${hero(s.short+' · SUBJECT OVERVIEW',s.name,'Build concepts. Track every topic.',s.color)}<section class="card summary"><div><p>Your syllabus progress</p><h2>${p.done} of ${p.total} topics completed</h2><span class="badge green">6 units</span> <span class="muted small">${p.total-p.done} topics remaining</span></div>${ring(p.pct)}</section><div class="section-heading"><h2>Your units</h2><span>Tap a unit to explore</span></div><div class="unit-list">${s.units.map(u=>{let x=percent(u.topics);return link(`<span class="unit-no ${u.color}">${String(u.id).padStart(2,'0')}</span><div class="unit-content"><div class="unit-title"><h3>${u.title}</h3>${u.important?'<span class="badge coral">☆ Important unit</span>':''}</div><p>${u.topics.map(t=>t.title).join(' · ')}</p><div class="unit-status"><small>${x.done} of ${x.total} topics</small><span class="badge ${x.pct===100?'green':'neutral'}">${x.pct===100?'✓ Completed':x.done?'In progress':'Not started'}</span></div>${bar(x.pct,u.color)}</div>${icon('chevron')}`,`/subjects/${s.id}/${u.id}`,'card unit-card');}).join('')}</div>`,{parent:'/subjects'});}
function unitPage(id,num){let s=subject(id),u=s.units.find(u=>u.id===+num)||s.units[0],p=percent(u.topics);let list=u.topics.filter(t=>unitFilter==='all'||(unitFilter==='done'?state.topics[t.id]:!state.topics[t.id]));return page(`${top(s.name,`Unit ${String(u.id).padStart(2,'0')} of 06`)}<div class="right-link">${link(icon('grid')+' All units','/subjects/'+s.id,'text-link')}</div>${hero('UNIT '+String(u.id).padStart(2,'0'),u.title,'Your topic checklist',u.color)}<section class="card summary"><div><p>Unit progress</p><h2>${p.done} of ${p.total} topics completed</h2><p>${p.total-p.done} topics left to cover</p></div>${ring(p.pct)}</section><div class="chips">${[['all',`All (${p.total})`],['pending',`Pending (${p.total-p.done})`],['done',`Completed (${p.done})`]].map(([v,t])=>btn(t,'unit-filter','chip '+(unitFilter===v?'selected':''),`data-value="${v}"`)).join('')}</div><div class="section-heading"><h2>Topic checklist</h2></div><p class="muted small">Tick a topic when you finish studying.</p><div class="topics">${list.map(t=>`<label class="card topic"><input type="checkbox" data-topic="${t.id}" ${state.topics[t.id]?'checked':''}><span class="check-ui">${icon('check')}</span><span class="topic-title">${t.title}</span><span class="badge ${state.topics[t.id]?'green':t.important?'coral':'neutral'}">${state.topics[t.id]?'✓ Done':t.important?'High priority':'Study'}</span></label>`).join('')||'<div class="card empty">No topics in this filter.</div>'}</div><div class="unit-travel">${u.id>1?link(icon('back')+`<div>Previous unit<small>${s.units[u.id-2].title}</small></div>`,`/subjects/${s.id}/${u.id-1}`,'button outline'):''}${link(`<div>${u.id<6?'Next unit':'All units'}<small>${u.id<6?s.units[u.id].title:'Back to the overview'}</small></div>`+icon('arrow'),u.id<6?`/subjects/${s.id}/${u.id+1}`:'/subjects/'+s.id,'button primary')}</div>`,{parent:'/subjects/'+s.id});}
function pyqIndex(){return page(`${hero('PREVIOUS YEAR QUESTIONS','Practice with purpose.','Important questions, organised by subject.','orange','paper')}<div class="card notice">${icon('document')}<div><h3>Important 7-mark written PYQs</h3><p>Browse by unit and see paper-year trends.</p></div></div><div class="section-heading"><h2>Choose your subject</h2><span>6 subjects</span></div>${subjectCards(s=>'/pyqs/'+s.id,'View important questions')}`,{active:'pyqs',main:true});}
function pyqSubject(id){let s=subject(id),all=pyqs(s.id),years=[2022,2023,2024,2025],counts=yearCounts(all,years),list=all.filter(q=>(unitFilter==='all'||q.unit===+unitFilter)&&(!savedOnly||state.saved.includes(q.id)));return page(`${top(s.name,'Important 7-mark PYQs')}${hero(s.short+' · QUESTION BANK','Important 7-mark PYQs','Unit-wise questions & paper-year trends.','orange','paper')}<div class="filter-row"><label class="sr-only" for="pyq-unit">Filter unit</label><select id="pyq-unit" data-change="pyq-unit"><option value="all">All units</option>${s.units.map(u=>`<option value="${u.id}" ${unitFilter==u.id?'selected':''}>Unit ${u.id} · ${u.title}</option>`).join('')}</select>${btn(icon('save')+' Saved','saved-filter','button outline '+(savedOnly?'is-active':''))}</div><div class="section-heading"><h2>Unit-wise important questions</h2></div><div class="pyq-list">${list.map(q=>`<article class="card pyq-card"><div class="pyq-title"><span class="badge ${colors[q.unit-1]}">Unit ${String(q.unit).padStart(2,'0')}</span><h3>${s.units[q.unit-1].title}</h3></div><p class="question-text">${esc(q.question)}</p><div class="years"><span class="badge orange">7 marks</span><span class="muted small">Asked in</span>${q.years.map(y=>`<span class="badge orange">${y}</span>`).join('')}</div><div class="pyq-actions">${btn(icon(state.marked.includes(q.id)?'check':'grid')+(state.marked.includes(q.id)?' Marked':' Mark'),'mark','text-link',`data-id="${q.id}" aria-pressed="${state.marked.includes(q.id)}"`)}${btn(icon('save')+(state.saved.includes(q.id)?' Saved':' Save'),'save-question','text-link '+(state.saved.includes(q.id)?'amber':''),`data-id="${q.id}" aria-pressed="${state.saved.includes(q.id)}"`)}</div></article>`).join('')||'<div class="card empty">No saved questions in this selection.</div>'}</div><section class="card analysis"><h2>Unit-wise year analysis</h2><p class="muted small">Illustrative counts across all sample paper appearances.</p><div class="table-scroll"><table><thead><tr><th>Unit</th>${years.map(y=>`<th>${y}</th>`).join('')}<th>Total</th></tr></thead><tbody>${counts.map((row,i)=>`<tr><th>${String(i+1).padStart(2,'0')}</th>${row.map(n=>`<td>${n}</td>`).join('')}<td><b>${row.reduce((a,b)=>a+b,0)}</b></td></tr>`).join('')}</tbody><tfoot><tr><th>Total</th>${years.map((_,j)=>`<td>${counts.reduce((a,r)=>a+r[j],0)}</td>`).join('')}<td>${counts.flat().reduce((a,b)=>a+b,0)}</td></tr></tfoot></table></div><p class="small muted">Unit classification follows the syllabus. Final years and counts will come from your papers; these are sample records.</p></section>`,{parent:'/pyqs'});}
function quizIndex(){return page(`${hero('QUIZ ZONE','Test yourself.<br>Grow stronger.','Choose your quiz type to get started.','purple','quiz')}<div class="section-heading"><h2>How would you like to practise?</h2></div><p class="muted">Pick a quiz type. Choose your subject next.</p>${[['pyq','FROM EXAM PAPERS','PYQ MCQ Quiz','Attempt original MCQs from previous-year question papers.','orange','paper','Year-wise questions · Answer explanations'],['master','SYLLABUS-BASED PRACTICE','Syllabus Master Quiz','Challenge your concepts with advanced syllabus-based MCQs.','purple','quiz','Unit-wise coverage · Mistake review']].map(([id,tag,title,sub,tone,art,features])=>link(`<span class="eyebrow">${tag}</span><img class="mode-art" src="./assets/${art==='paper'?'paper':'quiz'}.png" alt=""><h2>${title}</h2><p>${sub}</p><span class="mode-features">${features}</span><strong>Choose subject ${icon('arrow')}</strong>`,'/quiz/'+id,'card mode-card '+tone)).join('')}<p class="footnote">Your quiz progress stays on this device.</p>`,{active:'quiz',main:true});}
function quizSubjects(type){let master=type==='master';return page(`${top(master?'Syllabus Master Quiz':'PYQ MCQ Quiz','Quiz / Choose subject')}${hero(master?'SYLLABUS-BASED PRACTICE':'FROM PREVIOUS-YEAR PAPERS',master?'Go beyond memorising.':'Pick a subject.<br>Take the challenge.',master?'Understand. Apply. Master.':'Original exam MCQs, organised by subject.',master?'purple':'orange',master?'quiz':'paper')}<div class="card features"><span>${icon(master?'book':'calendar')}${master?'Unit-wise coverage':'Year-wise MCQs'}</span><span>${icon('info')}Explanations & review</span></div><div class="section-heading"><h2>Choose your subject</h2><span>6 subjects</span></div>${subjectCards(s=>`/quiz/${type}/${s.id}`,master?'Advanced syllabus-based MCQs':'Explore available paper years')}<p class="footnote">${master?'Practice questions · Separate from actual PYQs':'Review build · No verified PYQs loaded yet'}</p>`,{parent:'/quiz'});}
function quizSets(type,id){let s=subject(id),master=type==='master',a=state.attempts.find(a=>a.subject===s.id&&a.type===type&&!a.finished);return page(`${top(s.name,master?'Syllabus Master Quiz / Set up':'PYQ MCQ Quiz / Choose paper')}${hero(s.short+' · '+(master?'MASTER QUIZ':'PYQ MCQ QUIZ'),master?'Ready for a challenge?':'Learn from past papers.',master?'Choose your units and focus time.':'Choose a paper year to begin.',master?'purple':'orange',master?'quiz':'paper')}${a?`<div class="card resume"><h3>You have an unfinished quiz</h3><p>Your answers and active time are saved.</p>${link('Resume quiz '+icon('arrow'),'/attempt/'+a.id,'button primary')}</div>`:''}${master?`<form id="quiz-setup" class="card form-card" data-subject="${s.id}"><h2>Make this session yours</h2><label>Units<select name="unit"><option value="all">All units</option>${s.units.map(u=>`<option value="${u.id}">Unit ${u.id} · ${u.title}</option>`).join('')}</select></label><label>Time limit<select name="minutes"><option value="10">10 minutes</option><option value="20" selected>20 minutes</option><option value="30">30 minutes</option><option value="0">No limit · elapsed timer</option></select></label><div class="notice"><span>${quizQuestions(s.id).length} demo questions available. Final question counts follow your supplied content.</span></div><button class="primary full">Start master quiz ${icon('arrow')}</button></form>`:`<div class="section-heading"><h2>Year-wise quiz sets</h2><span>Sample sets</span></div>${[2025,2024,2023,2022].map((y,i)=>`<article class="card paper-card"><div class="year-tile ${colors[i]}">${icon('calendar')}<strong>${y}</strong></div><div><h2>${y} Paper</h2><p>Demo set · Not actual PYQs</p><span class="badge orange">${quizQuestions(s.id).length} sample MCQs</span></div>${btn('Start quiz '+icon('arrow'),'start-pyq','button amber-button',`data-subject="${s.id}" data-year="${y}"`)}</article>`).join('')}`}<div class="card notice">${icon('info')}<span>${master?'Answers and explanations appear after submission.':'Paper years and questions here are illustrative. Verified records will replace this demo bank.'}</span></div>`,{parent:'/quiz/'+type});}
function activeAttempt(){return state.attempts.find(a=>a.id===route()[1]);}
function startAttempt(s,type,year=null,unit='all',minutes=20,previousQuestions=null){let questions=previousQuestions||quizQuestions(s).filter(q=>unit==='all'||q.unit===+unit);if(!questions.length){toast('No questions for this unit yet.');return;}let a={id:uid(),subject:s,type,year,questions,answers:questions.map(()=>null),times:questions.map(()=>0),index:0,startedAt:Date.now(),elapsed:0,limit:+minutes*60,finished:false};state.attempts.push(a);save();go('/attempt/'+a.id);}
function capture(){let a=activeAttempt();if(a&&!a.finished&&currentStart!==null){let now=Date.now();let delta=Math.max(0,(now-currentStart)/1000);a.times=recordTime(a.times,a.index,currentStart,now);a.elapsed+=delta;currentStart=now;save();}}
function quizScreen(a){if(!a)return page(top('Quiz not found')+'<p>Return to Quiz to start a new attempt.</p>',{parent:'/quiz'});if(a.finished){go('/result/'+a.id);return '';}let s=subject(a.subject),q=a.questions[a.index];return `<div class="app-shell quiz-shell"><main><header class="quiz-header"><span>${s.name}</span><span class="timer">${icon('clock')}<b id="timer">${time(a.limit?Math.max(0,a.limit-a.elapsed):a.elapsed)}</b></span></header><div class="quiz-toolbar">${btn(icon('grid')+' Questions '+(navigatorOpen?'⌃':'⌄'),'navigator','button outline','aria-expanded="'+navigatorOpen+'"')}${btn('Exit','exit','button exit')}</div>${navigatorOpen?`<section class="question-dropdown card"><div class="section-heading"><h3>Jump to question</h3>${btn(icon('close'),'navigator','round','aria-label="Close question navigator"')}</div><div class="number-grid">${a.questions.map((_,i)=>btn(String(i+1)+(a.answers[i]!=null?'<small>✓</small>':''),'jump','number '+(a.answers[i]!=null?'answered ':'')+(a.index===i?'current':''),`data-index="${i}" aria-label="Question ${i+1}${a.answers[i]!=null?', answered':''}"`)).join('')}</div><p class="muted small">✓ Answered · Purple outline = current</p></section>`:''}<section class="card active-question"><h1>${esc(q.text)}</h1><div class="options">${q.options.map((o,i)=>btn(`<span class="radio"></span><span>${esc(o)}</span>`,'answer','option '+(a.answers[a.index]===i?'chosen':''),`data-value="${i}" role="radio" aria-checked="${a.answers[a.index]===i}"`)).join('')}</div></section><span class="quiz-demo">Sample question · Review build</span></main><div class="quiz-dock">${btn(icon('back')+' Back','previous','back-pill',a.index===0?'disabled':'')}${btn(a.index===a.questions.length-1?'Submit '+icon('check'):'Next '+icon('arrow'),a.index===a.questions.length-1?'submit-quiz':'next','next-pill')}</div></div>`;}
function finish(a){capture();a.finished=true;a.finishedAt=Date.now();currentStart=null;save();go('/result/'+a.id);}
function resultPage(id){let a=state.attempts.find(a=>a.id===id);if(!a)return page(top('Result not found'),{parent:'/history'});let r=scoreQuiz(a.questions,a.answers,a.times),status=r.score>=80?'Strong performance':r.score>=60?'Making progress':'Needs revision';return page(`${top('Quiz Results',subject(a.subject).name+' · '+(a.type==='master'?'Syllabus Master Quiz':a.year+' PYQ demo quiz'))}<section class="hero purple result-hero"><div><span class="eyebrow">QUIZ COMPLETED</span><h1>${r.correct} / ${r.total}</h1><h2>${r.score}% score</h2><span class="badge ${r.score>=80?'green':'coral'}">${status}</span><p>Every review is a step forward.</p></div><img class="result-art" src="./assets/quiz.png" alt="Quiz trophy"></section><div class="stat-grid"><div class="stat mint"><b>${r.correct}</b><span>Correct</span></div><div class="stat rose"><b>${r.wrong}</b><span>Wrong</span></div><div class="stat cream"><b>${r.skipped}</b><span>Skipped</span></div></div><section class="card"><h2>Time summary</h2><div class="two-stats"><div><p>Total active time</p><b>${time(r.totalSeconds)}</b></div><div><p>Average per question</p><b>${time(r.totalSeconds/r.total)}</b></div></div><p class="muted small">Includes revisits. Time away from the app is excluded.</p></section><section class="card"><h2>Performance snapshot</h2><div class="two-stats"><div><p>Attempt accuracy</p><b>${r.accuracy}%</b>${bar(r.accuracy,'purple')}</div><div><p>Completion</p><b>${Math.round(r.attempted/r.total*100)}%</b>${bar(r.attempted/r.total*100,'teal')}</div></div><p class="muted small">Status uses score: 80%+ strong, 60–79% making progress, below 60% needs revision. Speed alone does not determine performance.</p></section><div class="section-heading"><h2>Question-by-question review</h2></div><div class="chips">${[['all',`All (${r.total})`],['correct',`Correct (${r.correct})`],['wrong',`Wrong (${r.wrong})`],['skipped',`Skipped (${r.skipped})`]].map(([v,t])=>btn(t,'result-filter','chip '+(resultFilter===v?'selected purple-button':''),`data-value="${v}"`)).join('')}</div><div id="reviews">${a.questions.map((q,i)=>{let status=a.answers[i]==null?'skipped':a.answers[i]===q.answer?'correct':'wrong';if(resultFilter!=='all'&&resultFilter!==status)return '';return `<article class="card review"><div class="review-meta"><span class="badge purple">Q${i+1}</span><span class="badge ${status==='correct'?'green':status==='wrong'?'coral':'orange'}">${status}</span><span class="time-chip">${icon('clock')}${time(a.times[i])}</span></div><h3>${esc(q.text)}</h3><div class="answer-review"><div class="${status==='correct'?'mint':status==='wrong'?'rose':'cream'}"><small>Your answer</small><b>${a.answers[i]==null?'Not answered':esc(q.options[a.answers[i]])}</b></div><div class="mint"><small>Correct answer</small><b>${esc(q.options[q.answer])}</b></div></div><p class="explanation"><b>Explanation:</b> ${esc(q.explanation)}</p></article>`;}).join('')}</div><div class="action-row">${btn('Save & return to quizzes','save-result','button purple-button',`data-id="${a.id}"`)}${btn('Retry quiz','retry','button outline',`data-id="${a.id}"`)}</div>`,{parent:`/quiz/${a.type}/${a.subject}`});}
function taskRow(t){return `<div class="task-row"><input aria-label="Mark ${esc(t.title)} complete" type="checkbox" data-task="${t.id}" ${t.status==='done'?'checked':''}><div><h3>${esc(t.title)}</h3><p>${subject(t.subject).short} · ${t.minutes} min · ${formatDate(t.date)}</p></div>${t.status==='done'?'<span class="badge green">Done</span>':btn(icon('close'),'miss-task','round',`data-id="${t.id}" aria-label="Mark task missed"`)}</div>`;}
function planner(){let tasks=state.tasks.filter(t=>planFilter==='all'||(planFilter==='today'?t.date===dateKey():t.status==='missed'));return page(`${top('Preparation Planner','Small plans. Steady progress.')}${hero('MAKE TIME FOR WHAT MATTERS','Your path to exam day.','Plan a little. Learn a little. Every day.','blue')}<section class="card"><div class="section-heading"><h2>Exam schedule</h2></div><p class="small muted schedule-meta">All papers · ${examSession.label} IST</p><ol class="exam-schedule">${examSchedule.map(e=>{let sub=subject(e.subject),past=e.date<dateKey();return `<li class="exam-schedule-row"><span class="schedule-date ${sub.color}"><b>${new Date(e.date+'T12:00:00').getDate()}</b><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</small></span><div><span class="badge ${sub.color}">${sub.short}</span><h3>${sub.name}</h3><p><time datetime="${e.date}">${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short',year:'numeric'})}</time>${past?' · Completed':e.date===dateKey()?' · Today':''}</p></div></li>`;}).join('')}</ol><a href="${examSession.source}" class="text-link" target="_blank" rel="noopener">View official routine ${icon('arrow')}</a></section><section class="card"><h2>Your study plan</h2><p>Build 30-minute topic sessions around your availability and nearest exams.</p><div class="action-row">${btn('Build / refresh plan','generate-plan','button primary')}${link('Study preferences','/preferences','button outline')}</div><label class="toggle-row">Automatically reschedule pending work<input type="checkbox" id="auto-plan" ${state.settings.autoPlan?'checked':''}></label><p class="small muted">Completed tasks stay in your history. Missed tasks can be rescheduled.</p></section><form id="task-form" class="card form-card"><h2>Add a study task</h2><label>Task<input name="title" required maxlength="180" placeholder="e.g. Revise subnetting"></label><div class="form-grid"><label>Subject<select name="subject">${subjects.map(s=>`<option value="${s.id}">${s.short}</option>`).join('')}</select></label><label>Date<input name="date" type="date" required value="${dateKey()}"></label></div><button class="outline full">Add task</button></form><div class="chips">${[['today','Today'],['all','All tasks'],['missed','Missed']].map(([v,t])=>btn(t,'plan-filter','chip '+(planFilter===v?'selected':''),`data-value="${v}"`)).join('')}</div><section class="card task-list">${tasks.map(taskRow).join('')||'<div class="empty"><h3>Your plan is clear.</h3><p>Add a task or generate a study plan.</p></div>'}</section>`,{parent:'/home'});}
function regenerate(){let used=new Set(state.tasks.filter(t=>t.status==='done'||!t.auto).map(t=>t.topic));state.tasks=state.tasks.filter(t=>t.status==='done'||!t.auto);state.tasks.push(...buildPlan(allTopics.filter(t=>!used.has(t.id)),state.topics,dateKey(),state.settings.availability,examDates));save();}
function profileFooter(){const socialIcons={website:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18Z"/>',linkedin:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M7.5 10v7M7.5 7v.1M11 17v-7m0 3a3 3 0 0 1 6 0v4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>'};return `<footer class="profile-footer"><h2 id="follow-heading">Follow us on</h2><nav class="social-links" aria-labelledby="follow-heading">${[['website','Website'],['linkedin','LinkedIn'],['mail','Mail']].map(([id,label])=>{const content=`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${socialIcons[id]}</svg><span>${label}</span>`;return socialLinks[id]?`<a class="social-link" href="${esc(socialLinks[id])}" ${id!=='mail'?'target="_blank" rel="noopener noreferrer"':''}>${content}</a>`:`<button class="social-link" type="button" disabled aria-label="${label} — coming soon">${content}</button>`;}).join('')}</nav><p class="app-version" title="Build ${esc(buildId)}">v${esc(appVersion)}</p><div class="brand-signature"><p class="brand-shimmer">BEU Exam Dost</p><p class="brand-shimmer brand-byline">By BEU Developer</p></div></footer>`;}
function profile(){let p=percent(allTopics),done=state.attempts.filter(a=>a.finished),avg=done.length?Math.round(done.reduce((n,a)=>n+scoreQuiz(a.questions,a.answers,a.times).score,0)/done.length):0;return page(`${top('My Profile')}<section class="profile-hero lavender"><span class="avatar">${profileInitial()}</span><div><h1>${esc(state.profile.name)}</h1><p>${esc(state.profile.college)}</p><p>${esc(state.profile.branch)}</p><div class="chips"><span class="badge green">2024–28</span><span class="badge purple">Semester 4</span></div>${link('Edit profile','/edit-profile','button outline')}</div></section><div class="section-heading"><h2>Your preparation</h2></div><div class="stat-grid"><div class="stat mint"><b>${p.pct}%</b><span>Syllabus</span></div><div class="stat lavender"><b>${done.length}</b><span>Quizzes</span></div><div class="stat cream"><b>${avg}%</b><span>Avg. score</span></div></div><section class="card settings-list"><h2>Preferences</h2>${row('Study preferences','Daily availability & study goal','/preferences','settings','coral')}<div class="settings-row appearance-row">${icon('sun')}<span>Appearance</span><div class="theme-control"><span class="theme-label ${state.settings.theme==='light'?'is-selected':''}" aria-hidden="true">Light</span>${btn('<span class="theme-thumb"></span>','theme','theme-switch',`role="switch" aria-label="Dark mode" aria-checked="${state.settings.theme==='dark'}"`)}<span class="theme-label ${state.settings.theme==='dark'?'is-selected':''}" aria-hidden="true">Dark</span></div></div>${row('Study reminders','See today’s tasks in the app','/reminders','bell','green')}${row('Quiz history','Results & unfinished attempts','/history','clock','purple')}</section><section class="card settings-list"><h2>Your data</h2>${btn(icon('upload')+'<span>Export backup</span>'+icon('chevron'),'export','settings-row')}${btn(icon('download')+'<span>Import backup</span>'+icon('chevron'),'import','settings-row')}${row('Privacy & data sharing','Local storage and collection status','/privacy','info','purple')}</section><section class="card settings-list">${row('Install Exam Dost','Add to your phone','/install','download','orange')}</section>${profileFooter()}`,{parent:'/home'});}
function row(title,sub,path,ic,tone){return link(`<span class="mini-icon ${tone}">${icon(ic)}</span><span>${title}<small>${sub}</small></span>${icon('chevron')}`,path,'settings-row');}
function preferences(){return page(`${top('Study preferences','A routine that works for you')}<form id="preferences-form" class="card form-card"><h2>One primary goal</h2><label>My focus<select name="goal">${['Complete important topics','Revise the full syllabus','Improve MCQ accuracy','Focus on important PYQs'].map(g=>`<option ${state.settings.goal===g?'selected':''}>${g}</option>`).join('')}</select></label><h2>Daily availability</h2><p>Choose a separate study duration for every day.</p>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<label class="availability">${d}<select name="day${i}">${[0,30,60,90,120,180,240].map(n=>`<option value="${n}" ${+state.settings.availability[i]===n?'selected':''}>${n===0?'Day off':n+' minutes'}</option>`).join('')}</select></label>`).join('')}<label>Preferred study slot<select name="slot">${['Morning','Afternoon','Evening'].map(v=>`<option ${state.settings.slot===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary full">Save preferences</button></form>`,{parent:'/profile'});}
function historyPage(){return page(`${top('Quiz history','Your progress, one attempt at a time')}${state.attempts.length?[...state.attempts].reverse().map(a=>link(`<span class="subject-icon ${a.finished?'purple':'orange'}">${icon(a.finished?'trophy':'clock')}</span><div><h3>${subject(a.subject).short} · ${a.type==='master'?'Master Quiz':a.year+' Paper'}</h3><p>${a.finished?scoreQuiz(a.questions,a.answers,a.times).score+'% · Completed':'Saved · Resume attempt'}</p><small>${new Date(a.startedAt).toLocaleDateString('en-IN')}</small></div>${icon('chevron')}`,(a.finished?'/result/':'/attempt/')+a.id,'card history-card')).join(''):'<div class="card empty"><h2>Your first quiz is waiting.</h2><p>Completed results and saved attempts appear here.</p>'+link('Explore quizzes','/quiz','button purple-button')+'</div>'}`,{parent:'/profile'});}
function installPage(){return page(`${top('Install Exam Dost','Your study companion, one tap away')}${hero('TAKE YOUR STUDY WITH YOU','A little closer.<br>A little easier.','Choose how you want to use Exam Dost.','blue','phone')}<section class="card mode-card green"><span class="badge green">RECOMMENDED</span><h2>Install as PWA</h2><p>Add Exam Dost to your home screen from your browser.</p><div class="mode-features">Offline study content · No account needed</div>${btn('Add to home screen '+icon('download'),'install','button primary full')}</section><section class="card mode-card purple"><span class="badge orange">Coming later</span><h2>Android APK</h2><p>An Android package will be prepared after content and final hosting are ready.</p><button class="button outline full" disabled>APK not available yet</button></section><div class="card notice">${icon('info')}<span>Open online once and wait for “Offline ready” before relying on offline access. Installation availability depends on your browser and hosting.</span></div><p id="offline-status" class="footnote">${navigator.onLine?'You’re online':'You’re offline'}</p>`,{parent:'/profile'});}
function privacy(){return page(`${top('About & privacy','Built for steady, independent study')}<section class="card prose"><h2>Your device. Your progress.</h2><p>Exam Dost is an account-free study companion for the 2024–28 CSE cohort and supported specialisations.</p><h3>Stored locally</h3><p>Your profile, topic completion, saved questions, planner and quiz attempts are stored in this browser. Clearing site data can remove them. Export regular backups.</p><h3>Student records & analytics</h3><p>This review build does not transmit your name, college, branch, quiz scores or study activity to a collection service. No analytics tracker is enabled. A provider and clear disclosure will be added only after configuration.</p><h3>Demo content</h3><p>Unit labels, importance badges, paper years and questions are examples for reviewing the UI. They are not a verified question bank or official syllabus.</p><h3>Offline access</h3><p>After the first successful cache, app screens and bundled content work offline. Downloads and future profile submissions need connectivity.</p><h3>Backup safety</h3><p>Exports include your profile and study history. Keep them private. Importing a backup replaces this device’s app state after confirmation.</p><p class="muted small">Exam Dost · Review build 0.1.0</p></section>`,{parent:state.profile?'/profile':'/setup'});}
function reminders(){let t=state.tasks.filter(t=>t.date<=dateKey()&&t.status==='pending');return page(`${top('Study reminders','Your next small step')}<div class="card notice">${icon('bell')}<span>In-app reminders only. Background push notifications are not connected.</span></div><section class="card task-list">${t.map(taskRow).join('')||'<div class="empty">You’re all caught up. Add your next task in the planner.</div>'}</section>${link('Open planner','/planner','button primary')}`,{parent:'/home'});}
function formatDate(v){return new Date(v+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});}function time(n){n=Math.max(0,Math.floor(n||0));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function render(){let r=route();document.documentElement.dataset.theme=state.settings.theme;let html;if(!state.profile&&r[0]!=='privacy')html=setup();else switch(r[0]){case 'setup':html=state.profile?home():setup();break;case 'edit-profile':html=setup(true);break;case 'subjects':html=r[2]?unitPage(r[1],r[2]):r[1]?subjectPage(r[1]):subjectsPage();break;case 'pyqs':html=r[1]?pyqSubject(r[1]):pyqIndex();break;case 'quiz':html=r[2]?quizSets(r[1],r[2]):r[1]?quizSubjects(r[1]):quizIndex();break;case 'attempt':html=quizScreen(activeAttempt());break;case 'result':html=resultPage(r[1]);break;case 'planner':html=planner();break;case 'profile':html=profile();break;case 'preferences':html=preferences();break;case 'history':html=historyPage();break;case 'install':html=installPage();break;case 'privacy':html=privacy();break;case 'reminders':html=reminders();break;default:html=home();}$('#app').innerHTML=html;document.title=(r[0]?r[0][0].toUpperCase()+r[0].slice(1):'Welcome')+' · Exam Dost';}
function dialog(title,body,actions){let m=$('#modal');m.innerHTML=`<div class="dialog-inner"><h2>${title}</h2><p>${body}</p><div class="dialog-actions">${actions}</div></div>`;m.showModal();}
function closeDialog(){$('#modal').close();}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;let a=activeAttempt();switch(el.dataset.action){case'reminders':go('/reminders');break;case'unit-filter':unitFilter=el.dataset.value;render();break;case'saved-filter':savedOnly=!savedOnly;render();break;case'mark':case'save-question':{let arr=el.dataset.action==='mark'?state.marked:state.saved;let id=el.dataset.id,i=arr.indexOf(id);i<0?arr.push(id):arr.splice(i,1);save();render();break;}case'generate-plan':regenerate();render();toast('Study plan refreshed around your availability.');break;case'plan-filter':planFilter=el.dataset.value;render();break;case'miss-task':{let t=state.tasks.find(t=>t.id===el.dataset.id);t.status='missed';if(state.settings.autoPlan)regenerate();save();render();break;}case'start-pyq':startAttempt(el.dataset.subject,'pyq',+el.dataset.year,'all',10);break;case'navigator':navigatorOpen=!navigatorOpen;render();break;case'answer':capture();a.answers[a.index]=+el.dataset.value;save();render();break;case'jump':case'next':case'previous':capture();a.index=el.dataset.action==='jump'?+el.dataset.index:Math.max(0,Math.min(a.questions.length-1,a.index+(el.dataset.action==='next'?1:-1)));navigatorOpen=false;save();render();break;case'exit':capture();currentStart=null;dialog('Save and leave this quiz?','Your answers and active time will stay on this device. Resume when you’re ready.',btn('Keep studying','cancel','button outline')+btn('Save & exit','confirm-exit','button primary'));break;case'confirm-exit':closeDialog();save();go(`/quiz/${a.type}/${a.subject}`);break;case'cancel':closeDialog();if(a&&!a.finished)currentStart=Date.now();break;case'submit-quiz':capture();currentStart=null;dialog('Submit your quiz?',`${a.answers.filter(v=>v==null).length} unanswered question(s) will count as skipped.`,btn('Go back','cancel','button outline')+btn('Submit quiz','confirm-submit','button purple-button'));break;case'confirm-submit':closeDialog();finish(a);break;case'result-filter':resultFilter=el.dataset.value;render();break;case'save-result':save();if(storageOK){resultFilter='all';go('/quiz');toast('Quiz result saved.');}break;case'retry':{let old=state.attempts.find(a=>a.id===el.dataset.id);startAttempt(old.subject,old.type,old.year,'all',old.limit/60,old.questions);break;}case'theme':state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();render();$('.theme-switch')?.focus({preventScroll:true});break;case'export':{capture();let blob=new Blob([JSON.stringify({app:'exam-dost',version:1,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='exam-dost-backup-'+dateKey()+'.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exported. Keep it safe.');break;}case'import':{let f=document.createElement('input');f.type='file';f.accept='.json,application/json';f.onchange=async()=>{try{if(f.files[0].size>5e6)throw Error('Backup too large.');const next=validateBackup(JSON.parse(await f.files[0].text()));storePendingImport(next);}catch(err){toast('Could not import: '+err.message);}};f.click();break;}case'confirm-import':state={...blank(),...pendingImport,settings:{...blank().settings,...pendingImport.settings}};pendingImport=null;closeDialog();save();go('/profile');render();toast('Backup restored.');break;case'install':if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>{installPrompt=null;});}else{dialog('Install on your phone','In Chrome: open the browser menu and choose “Install app” or “Add to Home screen”. On iPhone: Safari → Share → Add to Home Screen. If unavailable, open the published site in your normal browser.',btn('Got it','cancel','button primary'));}break;}});
let pendingImport=null;function storePendingImport(s){pendingImport=s;dialog('Replace local study data?','Importing this backup replaces your current profile, progress and quiz history.',btn('Cancel','cancel','button outline')+btn('Restore backup','confirm-import','button primary'));}
document.addEventListener('change',e=>{let t=e.target;if(t.dataset.topic){state.topics[t.dataset.topic]=t.checked;if(state.settings.autoPlan)regenerate();save();render();}if(t.dataset.task){let task=state.tasks.find(v=>v.id===t.dataset.task);task.status=t.checked?'done':'pending';if(task.topic)state.topics[task.topic]=t.checked;if(state.settings.autoPlan)regenerate();save();render();}if(t.dataset.change==='pyq-unit'){unitFilter=t.value;render();}if(t.id==='auto-plan'){state.settings.autoPlan=t.checked;save();}});
document.addEventListener('submit',e=>{let f=e.target;if(!f.id)return;e.preventDefault();let d=new FormData(f);switch(f.id){case'profile-form':state.profile={name:d.get('name').trim(),college:d.get('college').trim(),branch:d.get('branch')};if(!state.profile.name||!state.profile.college){toast('Please enter your name and college.');return;}save();go(route()[0]==='edit-profile'?'/profile':'/home');render();break;case'task-form':state.tasks.push({id:uid(),title:d.get('title').trim(),subject:d.get('subject'),date:d.get('date'),minutes:30,status:'pending',auto:false});save();render();toast('Study task added.');break;case'preferences-form':state.settings.goal=d.get('goal');state.settings.slot=d.get('slot');state.settings.availability=Array.from({length:7},(_,i)=>+d.get('day'+i));if(state.settings.autoPlan)regenerate();save();go('/profile');toast('Study preferences saved.');break;case'quiz-setup':startAttempt(f.dataset.subject,'master',null,d.get('unit'),+d.get('minutes'));break;}});
window.addEventListener('hashchange',()=>{let old=previousHash;captureOld(old);scrolls.set(old,window.scrollY);viewStates.set(old,{unitFilter,savedOnly,resultFilter});previousHash=location.hash;navigatorOpen=false;const view=viewStates.get(location.hash)||{};unitFilter=view.unitFilter||'all';savedOnly=view.savedOnly||false;resultFilter=view.resultFilter||'all';currentStart=null;render();let a=activeAttempt();if(a&&!a.finished&&!document.hidden)currentStart=Date.now();window.scrollTo(0,scrolls.get(location.hash)||0);});
function captureOld(hash){if(!hash.startsWith('#/attempt/'))return;let id=hash.split('/')[2],a=state.attempts.find(a=>a.id===id);if(a&&!a.finished&&currentStart!==null){let now=Date.now();a.times=recordTime(a.times,a.index,currentStart,now);a.elapsed+=Math.max(0,(now-currentStart)/1000);save();}currentStart=null;}
document.addEventListener('visibilitychange',()=>{if(document.hidden){capture();currentStart=null;}else if(activeAttempt()&&!activeAttempt().finished&&!$('#modal').open)currentStart=Date.now();});
window.addEventListener('pagehide',()=>capture());
setInterval(()=>{let a=activeAttempt();if(a&&!a.finished&&currentStart!==null){capture();let timer=$('#timer');if(timer)timer.textContent=time(a.limit?Math.max(0,a.limit-a.elapsed):a.elapsed);if(a.limit&&a.elapsed>=a.limit){if($('#modal').open)closeDialog();finish(a);toast('Time is up. Your quiz has been submitted.');}}},1000);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('online',()=>toast('You’re back online.'));window.addEventListener('offline',()=>toast('Offline mode · Your saved content is available.'));
installUpdates({canReload:()=>!(activeAttempt()&&!activeAttempt().finished)&&!$('#modal').open,beforeReload:()=>{capture();save();return storageOK;},onReady:()=>toast('Offline ready · App content saved on this device.'),onDeferred:()=>toast('Update downloaded. It will apply after your current work.')} );
render();if(activeAttempt()&&!activeAttempt().finished)currentStart=Date.now();if(!storageOK)toast('Saved data could not be read. Import a backup if needed.');

$('#modal').addEventListener('cancel',()=>{let a=activeAttempt();if(a&&!a.finished&&!document.hidden)currentStart=Date.now();});
